(()=>{
const DATA=window.LEARNING_DATA,KEY="interview-sprint-v2",DAY=864e5,now=()=>Date.now(),today=()=>new Date().toISOString().slice(0,10);
const initial=()=>({version:2,items:{},questions:{},daily:{date:today(),count:0},goal:12});
let state=(()=>{try{return {...initial(),...JSON.parse(localStorage.getItem(KEY)||"{}")}}catch{return initial()}})();
state.version=2;
if(!state.daily||state.daily.date!==today())state.daily={date:today(),count:0};
let route="home",studyMode="zh-en",queue=[],index=0,interviewQueue=[],interviewIndex=0,libraryQuery="",libraryPriority="全部",libraryCategory="全部";
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const defaultItem=()=>({status:"new",reviews:0,errors:0,due:0,last:0,streak:0,favorite:false});
const getItem=(id,type="items")=>state[type][id]||defaultItem();
const setItem=(id,v,type="items")=>{state[type][id]={...getItem(id,type),...v};save()};
const counts=()=>{const s={known:0,fuzzy:0,again:0,new:0};DATA.cards.forEach(c=>s[getItem(c.id).status]++);return s};
const pct=()=>Math.round(counts().known/DATA.cards.length*100);
const dueCards=()=>DATA.cards.filter(c=>{const x=getItem(c.id);return x.due<=now()&&x.status!=="known"}).sort((a,b)=>{const A=getItem(a.id),B=getItem(b.id),rank={again:0,fuzzy:1,new:2,known:3},pr={"必须掌握":0,"高频":1,"加分":2};return rank[A.status]-rank[B.status]||pr[a.priority]-pr[b.priority]});
const dueCount=()=>dueCards().length;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const speech={voices:[],token:0};
const speechSupported=()=>"speechSynthesis" in window&&"SpeechSynthesisUtterance" in window;
function loadVoices(){if(!speechSupported())return[];const voices=window.speechSynthesis.getVoices();if(voices.length)speech.voices=voices;return speech.voices}
function speechChunks(text){const clean=String(text).replace(/\[[^\]]+\]/g,"something").replace(/\s+/g," ").trim(),sentences=clean.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[clean],chunks=[];let current="";sentences.forEach(sentence=>{const next=(current+" "+sentence.trim()).trim();if(current&&next.length>220){chunks.push(current);current=sentence.trim()}else current=next});if(current)chunks.push(current);return chunks}
function speechFallback(){toast("当前浏览器暂时无法播放语音，请尝试 Safari、Chrome 或 Edge。",4200)}
function speak(text){if(!speechSupported()){speechFallback();return}const synth=window.speechSynthesis,chunks=speechChunks(text),token=++speech.token;loadVoices();synth.cancel();let part=0;const play=()=>{if(token!==speech.token||part>=chunks.length)return;let started=false;const utterance=new SpeechSynthesisUtterance(chunks[part]);utterance.lang="en-US";utterance.rate=.88;utterance.pitch=1;utterance.voice=speech.voices.find(v=>v.lang==="en-US")||speech.voices.find(v=>v.lang.startsWith("en"))||null;utterance.onstart=()=>{started=true};utterance.onend=()=>{if(token===speech.token){part++;play()}};utterance.onerror=event=>{if(token===speech.token&&event.error!=="canceled"&&event.error!=="interrupted")speechFallback()};try{synth.speak(utterance);if(synth.paused)synth.resume();setTimeout(()=>{if(token===speech.token&&!started&&!synth.speaking)speechFallback()},1600)}catch{speechFallback()}};play()}
function toast(t,duration=1800){const n=document.querySelector("#toast");n.textContent=t;n.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove("show"),duration)}
function tags(c){const extra=(c.tags||[]).slice(1).filter(t=>t!==c.category).map(t=>`<span class="tag">${esc(t)}</span>`).join("");return `<div class="tags"><span class="tag ${c.priority==="必须掌握"?"must":""}">${c.priority}</span><span class="tag">${c.category}</span>${extra}</div>`}
function mini(c){return `<article class="mini-card">${tags(c)}<div class="english">${esc(c.en)}</div><div class="chinese">${esc(c.zh)}</div></article>`}
function home(){const s=counts(),remaining=Math.max(0,state.goal-state.daily.count);return `<section class="hero"><div class="eyebrow">你的短期面试训练</div><h1>${remaining?`今天再练 ${remaining} 个表达`:"今天的目标完成了"}</h1><p class="lead">${dueCount()} 个内容现在适合复习。先练能帮你完成回答的简单英语。</p></section><div class="dashboard-grid"><section class="progress-panel"><div class="progress-head"><div><div class="progress-number">${pct()}%</div><div class="progress-label">总体掌握进度 · 共 ${DATA.cards.length} 条</div></div><div class="progress-label">今日 ${state.daily.count}/${state.goal}</div></div><div class="meter"><span style="width:${pct()}%"></span></div><div class="stats"><div class="stat"><strong>${s.known}</strong><span>会了</span></div><div class="stat"><strong>${s.fuzzy}</strong><span>模糊</span></div><div class="stat"><strong>${s.again}</strong><span>不会</span></div></div></section><section class="actions"><button class="action-card primary" data-action="start-daily"><span><strong>开始今日学习</strong><small>到期内容优先，再学必须掌握</small></span><span class="arrow">→</span></button><button class="action-card" data-route="mock"><span><strong>文字模拟面试</strong><small>根据岗位与 JD 生成 5 题并诊断</small></span><span class="arrow">→</span></button><button class="action-card" data-route="review"><span><strong>快速复习</strong><small>不会、模糊、收藏、必学</small></span><span class="arrow">→</span></button><button class="action-card" data-route="interview"><span><strong>题库练习</strong><small>${DATA.questions.length} 道核心问题</small></span><span class="arrow">→</span></button></section></div><div class="section-title"><h2>先热身一个</h2><button class="text-button" data-route="library">查看全部</button></div>${mini(dueCards()[0]||DATA.cards[0])}`}
function buildDaily(){const due=dueCards(),rest=DATA.cards.filter(c=>!due.includes(c)).sort((a,b)=>({"必须掌握":0,"高频":1,"加分":2}[a.priority]-({"必须掌握":0,"高频":1,"加分":2}[b.priority])));queue=[...due,...rest].slice(0,12);index=0;studyMode="zh-en";navigate("study")}
function study(){if(!queue.length){queue=DATA.cards.slice(0,12);index=0}if(index>=queue.length)return doneView("本轮学习完成",`你练了 ${queue.length} 个表达。现在可以休息一下，或再做一轮快速复习。`);const c=queue[index],prompt=studyMode==="en-zh"?c.en:c.zh,dir=studyMode==="en-zh"?"英文 → 中文":studyMode==="card"?"学习卡":"中文 → 英文";return `<div class="study-wrap"><div class="hero"><div class="eyebrow">主动回忆 · ${dir}</div><h1>先说出口，再看答案</h1></div><div class="modebar" aria-label="学习模式"><button data-mode="zh-en" class="${studyMode==="zh-en"?"active":""}">中文 → 英文</button><button data-mode="en-zh" class="${studyMode==="en-zh"?"active":""}">英文 → 中文</button><button data-mode="card" class="${studyMode==="card"?"active":""}">学习卡</button></div><div class="study-progress"><span>${index+1} / ${queue.length}</span><span>${getItem(c.id).reviews} 次复习</span></div><article class="study-card"><div><div class="card-top">${tags(c)}<div class="row"><button class="star ${getItem(c.id).favorite?"on":""}" data-favorite="${c.id}" aria-label="收藏">★</button><button class="icon-button" data-speak="${esc(c.en)}" aria-label="朗读英文">◖))</button></div></div><div class="card-context">${esc(c.scene)}</div><div class="card-prompt">${esc(prompt)}</div><div id="answer">${studyMode==="card"?answerHTML(c):""}</div></div>${studyMode==="card"?"":'<button class="button full" id="reveal">查看答案</button>'}</article></div>`}
function answerHTML(c){return `<div class="answer"><div class="english">${esc(c.en)}</div><div class="chinese">${esc(c.zh)}</div><div class="example"><strong>自然例句</strong><br>${esc(c.example)} <button class="text-button" data-speak="${esc(c.example)}">朗读</button></div><div class="rating"><button class="again" data-rate="again">不会</button><button class="fuzzy" data-rate="fuzzy">模糊</button><button class="known" data-rate="known">会了</button></div></div>`}
function review(){const s=counts(),fav=DATA.cards.filter(c=>getItem(c.id).favorite).length,must=DATA.cards.filter(c=>c.priority==="必须掌握").length;return `<section class="hero"><div class="eyebrow">快速复习</div><h1>只练最需要的内容</h1><p class="lead">选择一个队列，仍然优先采用中文 → 英文主动回忆。</p></section><div class="review-grid"><button class="review-choice" data-review="again"><span class="count">${s.again}</span><strong>不会的</strong><small>很快再见一次</small></button><button class="review-choice" data-review="fuzzy"><span class="count">${s.fuzzy}</span><strong>模糊的</strong><small>巩固不确定表达</small></button><button class="review-choice" data-review="favorite"><span class="count">${fav}</span><strong>收藏的</strong><small>你的重点清单</small></button><button class="review-choice" data-review="must"><span class="count">${must}</span><strong>必须掌握</strong><small>面试前最后冲刺</small></button></div>`}
function buildQueue(items){queue=[...items];index=0;studyMode="zh-en";navigate("study")}
function rate(id,status,type="items"){const x=getItem(id,type),r=x.reviews+1;let delay;if(status==="again")delay=10*60*1000;else if(status==="fuzzy")delay=(r>2?3:1)*DAY;else delay=([2,5,10,21,45][Math.min(x.streak,4)]||45)*DAY;setItem(id,{status,reviews:r,errors:x.errors+(status==="again"?1:0),last:now(),due:now()+delay,streak:status==="known"?x.streak+1:0},type);state.daily.count++;save()}
function library(){const cats=["全部",...new Set(DATA.cards.map(c=>c.category))],ps=["全部","必须掌握","高频","加分"];const list=DATA.cards.filter(c=>(libraryPriority==="全部"||c.priority===libraryPriority)&&(libraryCategory==="全部"||c.category===libraryCategory)&&(!libraryQuery||(`${c.en} ${c.zh} ${c.scene}`).toLowerCase().includes(libraryQuery.toLowerCase())));return `<section class="hero"><div class="eyebrow">结构化词库</div><h1>全部表达 <span style="color:var(--muted);font-weight:500">(${list.length})</span></h1></section><div class="toolbar"><label><span class="sr-only">搜索</span><input id="search" class="search" value="${esc(libraryQuery)}" placeholder="搜索英文、中文或场景"></label><label><span class="sr-only">重要程度</span><select id="priority" class="search">${ps.map(x=>`<option ${x===libraryPriority?"selected":""}>${x}</option>`).join("")}</select></label><label><span class="sr-only">分类</span><select id="category" class="search">${cats.map(x=>`<option ${x===libraryCategory?"selected":""}>${x}</option>`).join("")}</select></label></div><div class="library-list">${list.length?list.map(c=>{const x=getItem(c.id);return `<article class="library-item"><button class="text-button" style="text-align:left;padding:0" data-open-card="${c.id}"><div class="english">${esc(c.en)}</div><div class="chinese">${esc(c.zh)}</div><div class="library-meta"><span class="status-pill">${c.priority}</span><span class="status-pill">${c.category}</span><span class="status-pill">${{new:"未学习",again:"不会",fuzzy:"模糊",known:"会了"}[x.status]}</span></div></button><div><button class="star ${x.favorite?"on":""}" data-favorite="${c.id}" aria-label="收藏">★</button><button class="icon-button" data-speak="${esc(c.en)}" aria-label="朗读">◖))</button></div></article>`}).join(""):`<div class="empty"><h2>没有匹配内容</h2><p>换一个关键词或筛选条件试试。</p></div>`}</div>`}
function interview(){if(!interviewQueue.length)interviewQueue=[...DATA.questions].sort(()=>Math.random()-.5);if(interviewIndex>=interviewQueue.length)return doneView("完整题库练完了","你已经开口回答了本轮所有问题。可以重新打乱再练，或回到首页。");const q=interviewQueue[interviewIndex],x=getItem(q.id,"questions");return `<div class="study-wrap"><div class="hero"><div class="eyebrow">面试练习 · ${q.category}</div><h1>先组织答案，再看参考</h1></div><div class="study-progress"><span>${interviewIndex+1} / ${interviewQueue.length}</span><span>${x.reviews} 次练习</span></div><article class="interview-card"><div><div class="card-top">${tags(q)}<button class="icon-button" data-speak="${esc(q.question)}" aria-label="朗读问题">◖))</button></div><div class="question">${esc(q.question)}</div><div class="question-zh">${esc(q.chinese)}</div><section class="answer-guide"><div class="guide-label">回答逻辑</div><p>${esc(q.answerStructure)}</p><div class="guide-label">关键表达</div><div class="keywords">${q.keyExpressions.map(k=>`<button class="keyword speak-chip" data-speak="${esc(k)}" aria-label="朗读：${esc(k)}">${esc(k)} <span aria-hidden="true">◖))</span></button>`).join("")}</div></section><div id="answer"></div></div><div class="card-actions"><button class="button full" id="reveal-interview">我已作答，查看参考内容</button></div></article></div>`}
function interviewAnswer(q){return `<div class="interview-answer"><details><summary>查看参考回答</summary><div class="detail-body reference">${esc(q.sampleAnswer)} <button class="text-button" data-speak="${esc(q.sampleAnswer)}">朗读回答</button></div></details><details><summary>查看中文翻译／逻辑说明</summary><div class="detail-body">${esc(q.explanation)}</div></details><details><summary>查看可能追问</summary><ul class="follow-ups">${q.followUps.map(f=>`<li><span>${esc(f)}</span><button class="text-button" data-speak="${esc(f)}" aria-label="朗读追问">朗读</button></li>`).join("")}</ul></details><div class="self-rating-label">这道题现在掌握得怎么样？</div><div class="rating"><button class="again" data-interview-rate="again">不会</button><button class="fuzzy" data-interview-rate="fuzzy">模糊</button><button class="known" data-interview-rate="known">会了</button></div></div>`}
function doneView(title,desc){return `<div class="study-wrap"><section class="session-done"><div class="big-check">✓</div><h1>${title}</h1><p class="lead" style="margin:0 auto 24px">${desc}</p><div class="row" style="justify-content:center"><button class="button" data-route="home">回到首页</button><button class="button secondary" data-route="review">继续复习</button></div></section></div>`}
function navigate(to){route=to;render();scrollTo({top:0,behavior:"smooth"})}
function render(){document.querySelectorAll(".bottom-nav [data-route]").forEach(b=>b.classList.toggle("active",b.dataset.route===route||(route==="review"&&b.dataset.route==="study")));document.querySelector("#view").innerHTML=route==="home"?home():route==="study"?study():route==="review"?review():route==="interview"?interview():route==="mock"?window.MockInterview.render():library();bind();if(route==="mock")window.MockInterview.bind({navigate,toast});document.querySelector("#view").focus({preventScroll:true})}
function bind(){
 document.querySelectorAll("[data-route]").forEach(b=>b.onclick=()=>navigate(b.dataset.route));
 document.querySelectorAll("[data-speak]").forEach(b=>b.onclick=()=>speak(b.dataset.speak));
 document.querySelectorAll("[data-favorite]").forEach(b=>b.onclick=()=>{const id=b.dataset.favorite,x=getItem(id);setItem(id,{favorite:!x.favorite});b.classList.toggle("on",!x.favorite);toast(!x.favorite?"已收藏":"已取消收藏")});
 document.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{studyMode=b.dataset.mode;render()});
 const reveal=document.querySelector("#reveal");if(reveal)reveal.onclick=()=>{const c=queue[index];document.querySelector("#answer").innerHTML=answerHTML(c);reveal.remove();bind()};
 document.querySelectorAll("[data-rate]").forEach(b=>b.onclick=()=>{rate(queue[index].id,b.dataset.rate);index++;render()});
 const ri=document.querySelector("#reveal-interview");if(ri)ri.onclick=()=>{const q=interviewQueue[interviewIndex];document.querySelector("#answer").innerHTML=interviewAnswer(q);ri.remove();bind()};
 document.querySelectorAll("[data-interview-rate]").forEach(b=>b.onclick=()=>{rate(interviewQueue[interviewIndex].id,b.dataset.interviewRate,"questions");interviewIndex++;render()});
 document.querySelectorAll("[data-review]").forEach(b=>b.onclick=()=>{const type=b.dataset.review,list=DATA.cards.filter(c=>type==="must"?c.priority==="必须掌握":type==="favorite"?getItem(c.id).favorite:getItem(c.id).status===type);if(!list.length){toast("这个队列暂时是空的");return}buildQueue(list)});
 const daily=document.querySelector("[data-action='start-daily']");if(daily)daily.onclick=buildDaily;
 const search=document.querySelector("#search");if(search)search.oninput=e=>{libraryQuery=e.target.value;clearTimeout(search.timer);search.timer=setTimeout(render,140)};
 const pri=document.querySelector("#priority");if(pri)pri.onchange=e=>{libraryPriority=e.target.value;render()};
 const cat=document.querySelector("#category");if(cat)cat.onchange=e=>{libraryCategory=e.target.value;render()};
 document.querySelectorAll("[data-open-card]").forEach(b=>b.onclick=()=>buildQueue([DATA.cards.find(c=>c.id===b.dataset.openCard)]));
}
document.querySelector("#soundTest").onclick=()=>speak("You are ready for your interview.");
document.querySelector(".brand").onclick=()=>navigate("home");
if(speechSupported()){loadVoices();if(window.speechSynthesis.addEventListener)window.speechSynthesis.addEventListener("voiceschanged",loadVoices);else window.speechSynthesis.onvoiceschanged=loadVoices}
if("serviceWorker" in navigator)addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:"start_interview_practice",title:"开始面试练习",description:"在应用中开始一轮英语面试问题练习。",inputSchema:{type:"object",properties:{category:{type:"string"}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({category}={})=>{const categories=[...new Set(DATA.questions.map(q=>q.category))];if(category&&!categories.includes(category))throw new Error("不支持的面试分类");interviewQueue=DATA.questions.filter(q=>!category||q.category===category).sort(()=>Math.random()-.5);interviewIndex=0;navigate("interview");return{started:true,count:interviewQueue.length}}})}catch{}}
save();render();
})();
